import sys,cv2,numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools');from rcb_brush import Session
T=np.array(Image.open('/app/target.png').convert('L'))<128
far=cv2.distanceTransform((~T).astype(np.uint8),cv2.DIST_L2,5)>4.5
s=Session(instance='/app/instance.json');a=np.load('/app/output/trajectory.npz')['actions'];s.reset()
for x in a:s.step(x)
s.painter.finish()
M=[]
for st in s.strokes():
 m=np.zeros((1024,1024),bool);r,c=st['mask_bbox'];raw=st['mask'];m[r:r+raw.shape[0],c:c+raw.shape[1]]=raw>=128;M.append(m)
def shift(m,du,dv):
 out=np.zeros_like(m);u0=max(0,-du);u1=min(1024,1024-du);v0=max(0,-dv);v1=min(1024,1024-dv)
 out[v0+dv:v1+dv,u0+du:u1+du]=m[v0:v1,u0:u1];return out
cur=[(0,0)]*len(M)
def metrics(P):
 inter=np.count_nonzero(P&T); union=np.count_nonzero(P|T); stray=np.count_nonzero(P&far)
 return inter/union,inter/T.sum(),stray/T.sum(),inter,stray
for sweep in range(3):
 for i in range(len(M)):
  oth=np.zeros((1024,1024),bool)
  for j,m in enumerate(M):
   if j!=i:oth|=shift(m,*cur[j])
  best=(-1,None,None)
  # search local +/- 8 from current shift
  base=cur[i]
  for dv in range(base[1]-8,base[1]+9):
   for du in range(base[0]-8,base[0]+9):
    cand=oth|shift(M[i],du,dv)
    met=metrics(cand)
    utility=met[3]-met[4]
    if utility>best[0]:best=(utility,(du,dv),met[:3])
  cur[i]=best[1]
 pred=np.zeros((1024,1024),bool)
 for m,sh in zip(M,cur):pred|=shift(m,*sh)
 print('sweep',sweep,'metrics',metrics(pred),'shifts',cur)
print('current relative',cur)
